ALTER TYPE "PaperStatus" ADD VALUE IF NOT EXISTS 'SPAM';
CREATE TABLE announcements (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), title STRING NOT NULL, content STRING NOT NULL, type STRING NOT NULL DEFAULT 'info' CHECK(type IN ('info','warning','alert','success')), is_active BOOL NOT NULL DEFAULT true, starts_at TIMESTAMPTZ NOT NULL DEFAULT now(), ends_at TIMESTAMPTZ, created_by_user_id UUID REFERENCES users(id), created_at TIMESTAMPTZ NOT NULL DEFAULT now(), deleted_at TIMESTAMPTZ, deleted_by_user_id UUID REFERENCES users(id), CHECK(ends_at IS NULL OR ends_at>starts_at)) WITH (schema_locked = false);
CREATE INDEX announcements_active_idx ON announcements(is_active,starts_at,ends_at) WHERE deleted_at IS NULL;
CREATE TABLE module_requests (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), requested_by_user_id UUID REFERENCES users(id), program_id UUID NOT NULL REFERENCES programs(id), module_code STRING NOT NULL, module_name STRING NOT NULL, academic_year_start INT2 NOT NULL CHECK(academic_year_start BETWEEN 2000 AND 2200), description STRING NOT NULL, semester INT2 NOT NULL CHECK(semester IN (1,2)), status STRING NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','approved','rejected')), reviewed_by_user_id UUID REFERENCES users(id), reviewed_at TIMESTAMPTZ, review_note STRING, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), deleted_at TIMESTAMPTZ, deleted_by_user_id UUID REFERENCES users(id)) WITH (schema_locked = false);
CREATE INDEX module_requests_status_idx ON module_requests(status,created_at DESC);
CREATE INDEX module_requests_user_idx ON module_requests(requested_by_user_id);
CREATE INDEX module_requests_program_idx ON module_requests(program_id,module_code);
CREATE INDEX module_requests_reviewer_idx ON module_requests(reviewed_by_user_id);
CREATE TABLE notifications (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), user_id UUID NOT NULL REFERENCES users(id), title STRING NOT NULL, type STRING NOT NULL CHECK(type IN ('xp','paper_approved','paper_rejected','announcement','system')), message STRING NOT NULL, link STRING, read_at TIMESTAMPTZ, created_at TIMESTAMPTZ NOT NULL DEFAULT now()) WITH (schema_locked = false);
CREATE INDEX notifications_user_idx ON notifications(user_id,created_at DESC);
CREATE INDEX notifications_unread_idx ON notifications(user_id,created_at DESC) WHERE read_at IS NULL;
CREATE TABLE paper_reviews (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), paper_id UUID NOT NULL REFERENCES papers(id), reviewer_user_id UUID NOT NULL REFERENCES users(id), action STRING NOT NULL CHECK(action IN ('approved','rejected','marked_spam','edited')), reason STRING NOT NULL DEFAULT '', corrected_title STRING, corrected_module_code STRING, created_at TIMESTAMPTZ NOT NULL DEFAULT now()) WITH (schema_locked = false);
CREATE INDEX reviews_paper_idx ON paper_reviews(paper_id,created_at DESC);
CREATE INDEX reviews_reviewer_idx ON paper_reviews(reviewer_user_id);
CREATE TABLE flagged_reports (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), paper_id UUID NOT NULL REFERENCES papers(id), reported_by_user_id UUID REFERENCES users(id), reason STRING NOT NULL CHECK(reason IN ('blurry_scan','wrong_module','copyright','duplicate','offensive','incomplete')), details STRING NOT NULL, status STRING NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','resolved','dismissed')), resolved_by_user_id UUID REFERENCES users(id), resolved_at TIMESTAMPTZ, resolution_note STRING, created_at TIMESTAMPTZ NOT NULL DEFAULT now()) WITH (schema_locked = false);
CREATE INDEX flags_status_idx ON flagged_reports(status,created_at DESC);
CREATE INDEX flags_paper_idx ON flagged_reports(paper_id);
CREATE INDEX flags_user_idx ON flagged_reports(reported_by_user_id);
CREATE INDEX flags_resolver_idx ON flagged_reports(resolved_by_user_id);
CREATE TABLE takedown_requests (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), paper_id UUID NOT NULL REFERENCES papers(id), requester_user_id UUID REFERENCES users(id), requester_full_name STRING NOT NULL, requester_email STRING NOT NULL, affiliation STRING NOT NULL, reason STRING NOT NULL, evidence STRING NOT NULL DEFAULT '', status STRING NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','approved_removed','rejected')), reviewed_by_user_id UUID REFERENCES users(id), reviewed_at TIMESTAMPTZ, review_note STRING, created_at TIMESTAMPTZ NOT NULL DEFAULT now()) WITH (schema_locked = false);
CREATE INDEX takedowns_status_idx ON takedown_requests(status,created_at DESC);
CREATE INDEX takedowns_paper_idx ON takedown_requests(paper_id);
CREATE INDEX takedowns_requester_idx ON takedown_requests(requester_user_id);
CREATE INDEX takedowns_reviewer_idx ON takedown_requests(reviewed_by_user_id);
CREATE TABLE achievement_definitions (id STRING PRIMARY KEY, title STRING NOT NULL, description STRING NOT NULL, category STRING NOT NULL CHECK(category IN ('submission','quality','speed','milestone','schemes')), xp_reward INT4 NOT NULL DEFAULT 0 CHECK(xp_reward>=0), icon_name STRING NOT NULL DEFAULT 'Award', max_progress INT4 NOT NULL DEFAULT 1 CHECK(max_progress>0), is_active BOOL NOT NULL DEFAULT true) WITH (schema_locked = false);
CREATE TABLE user_achievements (user_id UUID NOT NULL REFERENCES users(id), achievement_id STRING NOT NULL REFERENCES achievement_definitions(id), progress INT4 NOT NULL DEFAULT 0 CHECK(progress>=0), unlocked_at TIMESTAMPTZ, PRIMARY KEY(user_id,achievement_id)) WITH (schema_locked = false);
CREATE INDEX user_achievements_achievement_idx ON user_achievements(achievement_id);
CREATE TABLE contact_messages (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), sender_user_id UUID REFERENCES users(id), sender_name STRING NOT NULL, sender_email STRING NOT NULL, subject STRING NOT NULL, message STRING NOT NULL, status STRING NOT NULL DEFAULT 'new' CHECK(status IN ('new','in_progress','closed')), created_at TIMESTAMPTZ NOT NULL DEFAULT now()) WITH (schema_locked = false);
CREATE INDEX contact_sender_idx ON contact_messages(sender_user_id);
ALTER TABLE xp_ledger ADD COLUMN title STRING NOT NULL DEFAULT '';
ALTER TABLE xp_ledger ADD COLUMN paper_id UUID REFERENCES papers(id);
ALTER TABLE xp_ledger ADD COLUMN note STRING NOT NULL DEFAULT '';
ALTER TABLE xp_ledger ADD COLUMN status STRING NOT NULL DEFAULT 'applied' CHECK(status IN ('applied','pending_rescan'));
CREATE INDEX xp_paper_idx ON xp_ledger(paper_id);
ALTER TABLE xp_ledger ADD CONSTRAINT xp_event_type_check CHECK(event_type IN ('APPROVED_PAPER','MARKING_SCHEME','SUPPLEMENTARY','MILESTONE','ADMIN_ADJUSTMENT'));
ALTER TABLE xp_ledger ADD CONSTRAINT xp_grant_reason_check CHECK(event_type!='ADMIN_ADJUSTMENT' OR length(trim(reason))>0);
ALTER TABLE app_settings ADD COLUMN updated_by_user_id UUID REFERENCES users(id);
ALTER TABLE app_settings ADD COLUMN updated_at TIMESTAMPTZ NOT NULL DEFAULT now();
CREATE INDEX settings_actor_idx ON app_settings(updated_by_user_id);
ALTER TABLE audit_logs ADD COLUMN target_description STRING NOT NULL DEFAULT '';
ALTER TABLE stored_files ADD CONSTRAINT stored_files_owner_fkey FOREIGN KEY(owner_user_id) REFERENCES users(id);
ALTER TABLE papers ADD CONSTRAINT papers_reviewer_fkey FOREIGN KEY(reviewed_by_user_id) REFERENCES users(id);
CREATE INDEX stored_files_owner_idx ON stored_files(owner_user_id);
CREATE INDEX papers_reviewer_idx ON papers(reviewed_by_user_id);
CREATE INDEX papers_marking_idx ON papers(marking_scheme_file_id);
CREATE INDEX announcements_author_idx ON announcements(created_by_user_id);
CREATE INDEX audit_actor_idx ON audit_logs(actor_user_id);
CREATE INDEX username_registry_user_idx ON username_registry(user_id);
CREATE UNIQUE INDEX programs_code_live_key ON programs(code_normalized) WHERE deleted_at IS NULL;
CREATE UNIQUE INDEX modules_code_live_key ON modules(code_normalized) WHERE deleted_at IS NULL;
ALTER TABLE departments ADD CONSTRAINT departments_lengths_check CHECK(length(trim(code)) BETWEEN 2 AND 20 AND length(trim(name)) BETWEEN 2 AND 160);
ALTER TABLE programs ADD CONSTRAINT programs_lengths_check CHECK(length(trim(code)) BETWEEN 2 AND 30 AND length(trim(name)) BETWEEN 2 AND 200);
ALTER TABLE modules ADD CONSTRAINT modules_lengths_check CHECK(length(trim(code)) BETWEEN 2 AND 30 AND length(trim(name)) BETWEEN 2 AND 240);
ALTER TABLE users ADD CONSTRAINT users_lengths_check CHECK(length(full_name) BETWEEN 2 AND 160 AND length(bio)<=1000 AND length(username) BETWEEN 3 AND 30);
CREATE INDEX departments_active_idx ON departments(is_active) WHERE deleted_at IS NULL;
CREATE INDEX programs_active_idx ON programs(is_active) WHERE deleted_at IS NULL;
CREATE INDEX modules_active_idx ON modules(is_active) WHERE deleted_at IS NULL;
